        <div className="upload-photo">
          <label htmlFor="customImageUpload">Или загрузите своё изображение:</label>
          <input 
            type="file" 
            id="customImageUpload" 
            onChange={handleCustomImageUpload} 
          />
        </div>
        </div>
        <label>Выберите местоположение:</label>
        <MapComponent onLocationSelect={handleLocationSelect} /> {/* Включаем карту */}
        <label htmlFor="autocomplete">Название места:</label>
<Autocomplete
  onPlaceChanged={() => {
    const place = autocompleteRef.current.getPlace();
    const lat = place.geometry.location.lat();
    const lng = place.geometry.location.lng();
    setWeddingDetails(prev => ({
      ...prev,
      weddingLocation: place.formatted_address,
      locationCoords: { lat, lng },
    }));
